# 取得方式改用 input_data（跨版本最相容）
rows = [item["json"] for item in _items] if _items else []

if not rows:
    return [{"json": {"error": "No input detected"}}]

def escape_android(value):
    if value is None:
        return ""
    value = str(value)
    return value

en_lines = []
zh_lines = []

for row in rows:
    key = row.get("android name")
    if not key:
        continue

    en = escape_android(row.get("value(en)"))
    zh_raw = row.get("value(zh-TW)")
    zh = escape_android(zh_raw)

    en_lines.append(f'<string name="{key}">{en}</string>')
    zh_lines.append(f'<string name="{key}">{zh}</string>')

strings_en = '<resources>' + ''.join(en_lines) + '</resources>'
strings_zh = '<resources>' + ''.join(zh_lines) + '</resources>'

file_path_en = "app/src/main/res/values/strings.xml"
file_path_zh = "app/src/main/res/values-zh-rTW/strings.xml"

return [{
    "json": {
        "actions": [
            {
                "action": "update",
                "file_path": file_path_en,
                "content": strings_en
            },
            {
                "action": "update",
                "file_path": file_path_zh,
                "content": strings_zh
            }
        ],
        "strings_en": strings_en,
        "strings_zh": strings_zh
    }
}]

