# Decode base64 content from GitLab API and tag with language
items = [item["json"] for item in _items] if _items else []

def decode_base64_utf8(b64_string):
    if not b64_string:
        return ""
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    b64_string = b64_string.strip().replace('\n', '').replace('\r', '').replace(' ', '')
    byte_array = []
    buffer = 0
    bits = 0
    for char in b64_string:
        if char == '=':
            break
        if char not in alphabet:
            continue
        buffer = (buffer << 6) | alphabet.index(char)
        bits += 6
        if bits >= 8:
            bits -= 8
            byte = (buffer >> bits) & 0xFF
            byte_array.append(byte)
            buffer &= (1 << bits) - 1
    result = []
    i = 0
    while i < len(byte_array):
        byte = byte_array[i]
        if byte < 0x80:
            result.append(chr(byte))
            i += 1
        elif byte < 0xE0:
            if i + 1 < len(byte_array):
                char_code = ((byte & 0x1F) << 6) | (byte_array[i + 1] & 0x3F)
                result.append(chr(char_code))
                i += 2
            else:
                i += 1
        elif byte < 0xF0:
            if i + 2 < len(byte_array):
                char_code = ((byte & 0x0F) << 12) | ((byte_array[i + 1] & 0x3F) << 6) | (byte_array[i + 2] & 0x3F)
                result.append(chr(char_code))
                i += 3
            else:
                i += 1
        elif byte < 0xF8:
            if i + 3 < len(byte_array):
                char_code = ((byte & 0x07) << 18) | ((byte_array[i + 1] & 0x3F) << 12) | ((byte_array[i + 2] & 0x3F) << 6) | (byte_array[i + 3] & 0x3F)
                result.append(chr(char_code))
                i += 4
            else:
                i += 1
        else:
            i += 1
    return ''.join(result)

result = []
for item in items:
    lang = item.get("lang", "")
    if not lang:
        file_path = item.get("file_path", "")
        if "en.lproj" in file_path:
            lang = "en"
        elif "zh-Hant.lproj" in file_path:
            lang = "zh"
    decoded_content = decode_base64_utf8(item.get("content", ""))
    result.append({
        "json": {
            "_type": "existing_file",
            "lang": lang,
            "decoded_content": decoded_content
        }
    })

return result

# Convert Google Sheet rows to iOS Localizable.strings format
# Preserves Skip Keys area, deduplicates, updates changed values, %s -> %@
rows = [item["json"] for item in _items] if _items else []

if not rows:
    return [{"json": {"error": "No input detected"}}]

# Separate sheet rows from fetched existing file content
sheet_rows = []
existing_en_content = ""
existing_zh_content = ""

for row in rows:
    if row.get("_type") == "existing_file":
        decoded = row.get("decoded_content", "")
        if row.get("lang") == "en":
            existing_en_content = decoded
        elif row.get("lang") == "zh":
            existing_zh_content = decoded
    else:
        sheet_rows.append(row)

# Parse .strings content into dict of {key: value}
def parse_strings(content):
    result = {}
    for line in content.split("\n"):
        line = line.strip()
        if not line or line.startswith("//"):
            continue
        # Match pattern: "key" = "value";
        if line.startswith('"') and '" = "' in line and line.endswith('";'):
            sep = line.index('" = "')
            key = line[1:sep]
            val = line[sep+5:-2]
            result[key] = val
    return result

# Extract header (above // Localized Keys) and parse its key-values
def extract_header(content):
    if not content:
        return "", {}
    marker = "// Localized Keys"
    idx = content.find(marker)
    if idx == -1:
        return content, parse_strings(content)
    header = content[:idx]
    return header, parse_strings(header)

# Remove a key line from header text
def remove_key_from_header(header, key):
    lines = header.split("\n")
    filtered = []
    for line in lines:
        stripped = line.strip()
        if stripped.startswith('"' + key + '"') and '" = "' in stripped:
            continue
        filtered.append(line)
    return "\n".join(filtered)

# Process one language
def build_strings(existing_content, sheet_keys_values):
    header, header_dict = extract_header(existing_content)
    # Also parse existing Localized Keys section
    marker = "// Localized Keys"
    idx = existing_content.find(marker)
    existing_localized = {}
    if idx != -1:
        localized_section = existing_content[idx:]
        existing_localized = parse_strings(localized_section)
    all_existing = {}
    all_existing.update(header_dict)
    all_existing.update(existing_localized)
    updated_header = header
    new_lines = []
    for key, val in sheet_keys_values:
        # Replace %s with %@ for iOS
        val = val.replace("%s", "%@")
        if key in header_dict:
            if header_dict[key] == val:
                # Same value in Skip Keys, skip entirely
                continue
            else:
                # Different value, remove from header, add new to Localized Keys
                updated_header = remove_key_from_header(updated_header, key)
                new_lines.append(f'"{key}" = "{val}";')
        elif key in existing_localized:
            if existing_localized[key] == val:
                # Same value already in Localized Keys, keep as is
                new_lines.append(f'"{key}" = "{val}";')
            else:
                # Different value, use new value
                new_lines.append(f'"{key}" = "{val}";')
        else:
            # New key
            new_lines.append(f'"{key}" = "{val}";')
    new_section = "// Localized Keys\n" + "\n".join(new_lines) + "\n"
    return updated_header + new_section

# Build key-value lists from sheet for each language
en_kv = []
zh_kv = []
for row in sheet_rows:
    key = row.get("iOS name")
    if not key:
        continue
    en = str(row.get("value(en)", "") or "")
    zh = str(row.get("value(zh-TW)", "") or "")
    en_kv.append((key, en))
    zh_kv.append((key, zh))

strings_en = build_strings(existing_en_content, en_kv)
strings_zh = build_strings(existing_zh_content, zh_kv)

file_path_en = "en.lproj/Localizable.strings"
file_path_zh = "zh-Hant.lproj/Localizable.strings"

return [{
    "json": {
        "actions": [
            {
                "action": "update",
                "file_path": file_path_en,
                "content": strings_en
            },
            {
                "action": "update",
                "file_path": file_path_zh,
                "content": strings_zh
            }
        ],
        "strings_en": strings_en,
        "strings_zh": strings_zh
    }
}]

