const generatedEn = $('Code to localization.strings in Python').first().json.strings_en || '';
const generatedZh = $('Code to localization.strings in Python').first().json.strings_zh || '';

const fetchedFiles = $input.all();
let existingEn = '';
let existingZh = '';

for (const item of fetchedFiles) {
  if (item.json.lang === 'en') existingEn = item.json.decoded_content || '';
  if (item.json.lang === 'zh') existingZh = item.json.decoded_content || '';
}

const changed = generatedEn !== existingEn || generatedZh !== existingZh;
return [{ json: { changed } }];

const required = [
  'gitlab_base_url',
  'android_project_id',
  'android_base_branch',
  'ios_project_id',
  'ios_base_branch',
  'sheet_id',
  'sheet_gid',
];

const cfg = $input.first().json;
const missing = required.filter(k => cfg[k] === undefined || cfg[k] === null || cfg[k] === '');

if (missing.length > 0) {
  throw new Error(
    'LocaleSync: missing required config fields from caller: ' + missing.join(', ') + '. '
    + 'Pass all fields via the Execute Workflow node in the parent workflow.'
  );
}

return [$input.first()];
